package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// AdoptOptions configures Adopt. The embedded CreateOptions carries the
// fetch-and-resolve half (template, version, values, sets, prompter
// inputs, library coordinates); adopt adds the target directory and the
// record-only concerns.
type AdoptOptions struct {
	CreateOptions

	// ProjectDir is the existing component root the record is written
	// into. Required; adopt never creates it.
	ProjectDir string

	// DependsOn populates the record's dependsOn. Each Dir must exist
	// relative to ProjectDir.
	DependsOn []DependencyRecord

	// DryRun prints the record and report without writing anything.
	DryRun bool
}

// Adopt writes a scaffold record for an existing component without
// rendering anything: it resolves the template release and values exactly
// as Create would, validates the record against the block parser registry
// system assembly uses, and writes .intropy/scaffold.json. Source files
// are never touched.
func Adopt(ctx context.Context, opts AdoptOptions) error {
	opts.ProjectDir = strings.TrimSpace(opts.ProjectDir)
	if opts.ProjectDir == "" {
		return errors.New("project directory is required")
	}

	p, err := PrepareCreate(ctx, opts.CreateOptions)
	if err != nil {
		return err
	}
	defer p.Cleanup()

	// Adopt records block components and shared libraries only; a system
	// host's record is created by sys create and carries a different
	// payload.
	if role := roleFromLabels(p.Manifest.Metadata.Labels); role == RoleSystemHost {
		return fmt.Errorf("template %q is a system host; its record is created by 'sys create', not adopted", opts.Template)
	}

	recordPath := RecordPath(opts.ProjectDir)

	// The record must parse under the same rules sys create will apply
	// later, or adoption just defers the failure to assembly time.
	if kind := blockKindFromLabels(p.Manifest.Metadata.Labels); kind != "" {
		if err := ValidateBlockRecord(kind, p.Values, recordPath); err != nil {
			return err
		}
	}

	info, err := os.Stat(opts.ProjectDir)
	if err != nil {
		return fmt.Errorf("stat project directory: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("project directory %s is not a directory", opts.ProjectDir)
	}

	if _, err := os.Stat(recordPath); err == nil && !opts.Force {
		return fmt.Errorf("%s already exists (use --force to overwrite)", recordPath)
	} else if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("stat %s: %w", recordPath, err)
	}

	for _, d := range opts.DependsOn {
		depInfo, err := os.Stat(filepath.Join(opts.ProjectDir, filepath.FromSlash(d.Dir)))
		if err != nil {
			return fmt.Errorf("dependency %s: %w", d.Dir, err)
		}
		if !depInfo.IsDir() {
			return fmt.Errorf("dependency %s is not a directory", d.Dir)
		}
	}

	scaffold := buildScaffold(p.Template, p.Owner, p.Repo, p.Version, p.Values, p.Manifest.Metadata.Labels, opts.DependsOn)

	if opts.DryRun {
		data, err := json.MarshalIndent(scaffold, "", "  ")
		if err != nil {
			return err
		}
		fmt.Fprintf(opts.Stdout, "%s\n", data)
		printAdoptReport(opts.Stderr, opts.ProjectDir, scaffold, true)
		return nil
	}

	if err := WriteScaffold(opts.ProjectDir, scaffold); err != nil {
		return err
	}
	printAdoptReport(opts.Stderr, opts.ProjectDir, scaffold, false)
	return nil
}

// printAdoptReport summarizes the adopted record on stderr: where it came
// from, what it carries, and the drift hints a pre-template component
// should be checked against.
func printAdoptReport(w io.Writer, projectDir string, s Scaffold, dryRun bool) {
	if w == nil {
		return
	}
	action := "adopted"
	if dryRun {
		action = "would adopt"
	}
	fmt.Fprintf(w, "%s %s as %s/%s@%s (template %s)\n", action, projectDir, s.Owner, s.Repo, s.Version, s.Template)

	keys := make([]string, 0, len(s.Values))
	for k := range s.Values {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Fprintf(w, "  %s: %v\n", k, s.Values[k])
	}
	for _, d := range s.DependsOn {
		fmt.Fprintf(w, "  depends on %s at %s\n", d.Template, d.Dir)
	}

	for _, hint := range driftHints(projectDir, s) {
		fmt.Fprintf(w, "warning: %s\n", hint)
	}
	fmt.Fprintln(w, "note: source files were not touched; 'int create --with-docs' scaffolding for existing projects is not available yet")
}

// driftHints checks the record against what is actually on disk. These
// are warnings, never failures: the record is the source of truth going
// forward, and the hints name where the pre-template code disagrees.
func driftHints(projectDir string, s Scaffold) []string {
	var hints []string

	if name, ok := s.Values["projectName"].(string); ok && name != "" {
		if !hasCsproj(projectDir, name) {
			hints = append(hints, fmt.Sprintf("no %s.csproj found under %s — the record's projectName does not match any project file; system assembly will reference a project that is not there", name, projectDir))
		}
	}

	for _, d := range s.DependsOn {
		dir := filepath.Join(projectDir, filepath.FromSlash(d.Dir))
		if !dirHasCsproj(dir) {
			hints = append(hints, fmt.Sprintf("dependency dir %s contains no .csproj — check the dependsOn path", d.Dir))
		}
	}

	if appID, ok := s.Values["appId"].(string); ok && appID != "" {
		hints = append(hints, fmt.Sprintf("verify the Dapr app-id in the component's configuration matches the record's appId %q", appID))
	}

	return hints
}

// hasCsproj reports whether a file named <name>.csproj exists anywhere
// under root.
func hasCsproj(root, name string) bool {
	want := name + ".csproj"
	found := false
	_ = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || found {
			return nil
		}
		if d.IsDir() && listSkipDirs[d.Name()] {
			return fs.SkipDir
		}
		if !d.IsDir() && d.Name() == want {
			found = true
		}
		return nil
	})
	return found
}

// dirHasCsproj reports whether any .csproj exists directly in dir.
func dirHasCsproj(dir string) bool {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false
	}
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".csproj") {
			return true
		}
	}
	return false
}

package system

import (
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// TestAssembleAdoptedRecord proves the adoption loop: a record written for
// a pre-template component (the record-only half of `int adopt`, run here
// against a fixture so no template fetch is needed) assembles into a
// component with the wiring sys create generates code from.
func TestAssembleAdoptedRecord(t *testing.T) {
	workspace := t.TempDir()
	componentDir := workspace + "/Extractor.Pim"

	record := template.Scaffold{
		SchemaVersion: template.ScaffoldSchemaVersion,
		Template:      "extractor",
		Owner:         "integrio-intropy",
		Repo:          "intropy-templates",
		Version:       "v1.2.3",
		Values: map[string]any{
			"name":         "Extractor.Pim",
			"organization": "fluxia",
			"topic":        "product-export",
			"contract":     "ExportEvent",
			"pubsub":       "pubsub",
			"appId":        "product-distribution-extractor-pim",
			"projectName":  "Extractor.Pim",
			"port":         "pim-extractor-source",
		},
		BlockKind: template.BlockKindExtractor,
		DataFlow:  "in",
		DependsOn: []template.DependencyRecord{{Template: "shared-contracts", Dir: "../shared"}},
	}
	if err := template.WriteScaffold(componentDir, record); err != nil {
		t.Fatal(err)
	}

	// The adopted record must pass the same validation gate adopt applies.
	if err := template.ValidateBlockRecord(record.BlockKind, record.Values, template.RecordPath(componentDir)); err != nil {
		t.Fatalf("ValidateBlockRecord: %v", err)
	}

	entries, warnings := template.ListScaffolds(workspace)
	if len(warnings) != 0 {
		t.Fatalf("scan warnings: %v", warnings)
	}

	var warnMsgs []string
	model, err := Assemble(entries, func(format string, args ...any) {
		warnMsgs = append(warnMsgs, format)
	})
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}

	if len(model.Components) != 1 {
		t.Fatalf("components = %+v, want exactly one", model.Components)
	}
	c := model.Components[0]
	if c.AppID != "product-distribution-extractor-pim" {
		t.Errorf("AppID = %q", c.AppID)
	}
	if c.Kind != template.BlockKindExtractor {
		t.Errorf("Kind = %q", c.Kind)
	}
	if c.Topic == nil || c.Topic.Name != "product-export" || c.Topic.Pubsub != "pubsub" {
		t.Errorf("Topic = %+v", c.Topic)
	}
	if c.Port != "pim-extractor-source" || len(c.Ports) != 1 {
		t.Errorf("Port/Ports = %q/%v", c.Port, c.Ports)
	}
	if len(model.Topics) != 1 || model.Topics[0].Contract != "ExportEvent" {
		t.Errorf("Topics = %+v", model.Topics)
	}
}

package main

import (
	"fmt"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/spf13/cobra"
)

type adoptFlags struct {
	dir             string
	name            string
	templateVersion string
	templateRepo    string
	values          []string
	sets            []string
	dependsOn       []string
	dryRun          bool
	force           bool
	noInput         bool
}

var intAdoptFlags adoptFlags

var intAdoptCmd = &cobra.Command{
	Use:   "adopt <template> [project-file]",
	Short: "Record an existing component as scaffolded from a template",
	Long: `Record an existing component as scaffolded from a template, without touching its source files.

Adopt fetches the template release, resolves values exactly as 'int create' would, validates the record against the rules 'sys create' assembles, and writes .intropy/scaffold.json into the component directory. After adoption the component appears in 'int list' and can be assembled by 'sys create'.

Give the component's project file and adopt derives the rest: the component directory, the record's projectName, and — unless --name says otherwise — the integration name. Without a project file the directory defaults to the current one (or --dir).

Example — adopt the pre-template PIM extractor from the workspace root:

  intropy int adopt extractor Extractor.Pim/Extractor.Pim.csproj \
    -s organization=fluxia -s topic=product-export -s contract=ExportEvent \
    -s appId=product-distribution-extractor-pim \
    -s port=pim-extractor-source --depends-on shared-contracts:../shared

An existing scaffold.json requires --force to overwrite. --dry-run prints the record and report without writing.`,
	Args: cobra.RangeArgs(1, 2),
	RunE: func(cmd *cobra.Command, args []string) error {
		sets, err := template.ParseSets(intAdoptFlags.sets)
		if err != nil {
			return err
		}
		dir := intAdoptFlags.dir
		if len(args) == 2 {
			if dir != "" {
				return newUsageErrorf("cannot combine a project file argument with --dir (they conflict)")
			}
			var err error
			dir, err = adoptDirFromCsproj(args[1], sets)
			if err != nil {
				return err
			}
		}
		name := intAdoptFlags.name
		if name == "" {
			if n, ok := sets["projectName"].(string); ok && n != "" {
				name = n
			} else if len(args) == 2 {
				name = csprojBaseName(args[1])
			} else if dir != "" && dir != "." {
				name = filepath.Base(filepath.Clean(dir))
			}
		}
		if _, err := resolveCreateName(name, "", sets); err != nil {
			return err
		}
		deps, err := parseDependsOn(intAdoptFlags.dependsOn)
		if err != nil {
			return err
		}
		owner, repo, err := resolveTemplateRepo(intAdoptFlags.templateRepo)
		if err != nil {
			return err
		}
		if dir == "" {
			dir = "."
		}
		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()
		return template.Adopt(ctx, template.AdoptOptions{
			CreateOptions: template.CreateOptions{
				Template:  args[0],
				Version:   intAdoptFlags.templateVersion,
				SetValues: sets,
				Files:     intAdoptFlags.values,
				NoInput:   intAdoptFlags.noInput,
				Force:     intAdoptFlags.force,
				Stdin:     cmd.InOrStdin(),
				Stdout:    cmd.OutOrStdout(),
				Stderr:    cmd.ErrOrStderr(),
				UserAgent: "intropy-cli/" + version,
				Owner:     owner,
				Repo:      repo,
			},
			ProjectDir: dir,
			DependsOn:  deps,
			DryRun:     intAdoptFlags.dryRun,
		})
	},
}

// adoptDirFromCsproj derives the component directory and projectName from
// a positional project file argument. The file must exist on disk; its
// directory becomes the component root and its base name the record's
// projectName, unless --set already pins projectName to the same value.
func adoptDirFromCsproj(path string, sets map[string]any) (string, error) {
	base := csprojBaseName(path)
	if base == "" {
		return "", newUsageErrorf("%q is not a .csproj file", path)
	}
	info, err := os.Stat(path)
	if err != nil {
		return "", fmt.Errorf("stat project file: %w", err)
	}
	if info.IsDir() {
		return "", newUsageErrorf("%q is a directory, not a .csproj file", path)
	}
	if pn, ok := sets["projectName"]; ok && pn != base {
		return "", newUsageErrorf("project file %q conflicts with --set projectName=%v", path, pn)
	}
	sets["projectName"] = base
	return filepath.Dir(path), nil
}

// csprojBaseName returns the project name a .csproj path carries, or the
// empty string when the path does not name a .csproj file.
func csprojBaseName(path string) string {
	base := filepath.Base(path)
	if !strings.HasSuffix(base, ".csproj") {
		return ""
	}
	return strings.TrimSuffix(base, ".csproj")
}

// parseDependsOn parses repeatable --depends-on flags of the form
// <template>:<dir>. The dir is relative to the component root and
// slash-separated, matching the record's DependencyRecord shape.
func parseDependsOn(items []string) ([]template.DependencyRecord, error) {
	var deps []template.DependencyRecord
	for _, item := range items {
		templateName, dir, ok := strings.Cut(item, ":")
		if !ok || templateName == "" || dir == "" || strings.Contains(dir, ":") {
			return nil, newUsageErrorf("invalid --depends-on %q (expected <template>:<dir>, e.g. shared-contracts:../shared)", item)
		}
		deps = append(deps, template.DependencyRecord{Template: templateName, Dir: dir})
	}
	return deps, nil
}

func init() {
	f := intAdoptCmd.Flags()
	f.StringVar(&intAdoptFlags.dir, "dir", "", "existing component root (default: current directory or the project file's directory)")
	_ = intAdoptCmd.MarkFlagDirname("dir")
	f.StringVarP(&intAdoptFlags.name, "name", "n", "", "integration name (default: the project file's base name); sets the template's 'name' parameter")
	f.StringVar(&intAdoptFlags.templateVersion, "template-version", "", flagUsageTemplateVer)
	f.StringVar(&intAdoptFlags.templateRepo, "template-repo", "", flagUsageTemplateRepo)
	f.StringArrayVarP(&intAdoptFlags.values, "values", "f", nil, "values file in YAML/JSON (repeatable; use - to read one doc from stdin)")
	f.StringArrayVarP(&intAdoptFlags.sets, "set", "s", nil, "set a value as key=value (repeatable)")
	f.StringArrayVar(&intAdoptFlags.dependsOn, "depends-on", nil, "sibling dependency as <template>:<dir>, dir relative to the component root (repeatable)")
	f.BoolVar(&intAdoptFlags.dryRun, "dry-run", false, "print the record and report without writing anything")
	f.BoolVar(&intAdoptFlags.force, "force", false, "overwrite an existing .intropy/scaffold.json")
	f.BoolVar(&intAdoptFlags.noInput, "no-input", false, flagUsageNoInput)
	intCmd.AddCommand(intAdoptCmd)
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.dev/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.dev/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in", "out",
	// or "both"). Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.dev/data-flow"

	// The BlockKind constants name the block kinds with a parse entry in
	// internal/system's blockParsers registry — the set `sys create`
	// assembles. Records carrying any other kind are skipped with a
	// warning.
	BlockKindExtractor     = "extractor"
	BlockKindLoader        = "loader"
	BlockKindTransactional = "transactional-integration"
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.dev/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.dev/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.dev/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// buildScaffold assembles the record every record-writing command shares,
// so create, adopt, and the dashboard cannot drift on the shape. template
// is the repo directory name, not the manifest's metadata.name — it is
// what a later re-fetch needs.
func buildScaffold(template string, owner, repo, tag string, values map[string]any, labels map[string]string, deps []DependencyRecord) Scaffold {
	return Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      template,
		Owner:         owner,
		Repo:          repo,
		Version:       tag,
		Values:        values,
		Role:          roleFromLabels(labels),
		BlockKind:     blockKindFromLabels(labels),
		DataFlow:      dataFlowFromLabels(labels),
		DependsOn:     deps,
	}
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}

package system

import (
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ErrNoComponents is returned when the workspace scan finds no scaffold
// record `sys create` can assemble into a component.
var ErrNoComponents = errors.New("no assemblable integration scaffolds found")

// Assemble classifies workspace scaffold records into a system model:
// shared-library records become the referenced contract project, records
// with a kind in the blockParsers registry become components, and
// everything else is skipped through warnf. The returned model's
// Name/ProjectName/SystemClass are left empty — the caller fills them
// around the template render.
func Assemble(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	var (
		components []Component
		shared     []SharedLibrary
		byAppID    = map[string]string{}   // appId -> scaffold dir
		byTopic    = map[TopicKey]Topic{}  // key -> first-seen topic
		firstDir   = map[TopicKey]string{} // key -> dir that defined it
		byPort     = map[string]string{}   // port -> scaffold dir
	)

	for _, e := range entries {
		switch {
		case e.Role == template.RoleSharedLibrary:
			name, err := stringValue(e, "name")
			if err != nil {
				return nil, err
			}
			shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
			continue
		case e.Role == template.RoleSystemHost:
			warnf("skipping %s: an existing system host", e.Path)
			continue
		case e.BlockKind == "":
			warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
			continue
		}

		if _, ok := template.BlockParsers[e.BlockKind]; !ok {
			warnf("skipping %s: unsupported block kind %q (sys create assembles %s)", e.Path, e.BlockKind, strings.Join(template.SupportedBlockKinds(), ", "))
			continue
		}

		appID, err := stringValue(e, "appId")
		if err != nil {
			return nil, err
		}
		c := Component{AppID: appID, Kind: e.BlockKind, Path: e.Path}
		if err := parseBlock(e, &c); err != nil {
			return nil, err
		}
		if c.missingPort {
			warnf("%s: scaffold record has no port — re-scaffold with a newer template release to wire From/To", e.Path)
		}

		if prev, ok := byAppID[appID]; ok {
			return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
		}
		byAppID[appID] = e.Path

		for _, port := range c.Ports {
			if prev, ok := byPort[port]; ok {
				return nil, fmt.Errorf("duplicate port %q: declared by both %s and %s (each block gets its own port; rename one in the record's values)", port, prev, e.Path)
			}
			byPort[port] = e.Path
		}

		if c.Topic != nil {
			key := *c.Topic
			if seen, ok := byTopic[key]; ok {
				if seen.Contract != c.topicContract {
					return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", key.Name, key.Pubsub, seen.Contract, firstDir[key], c.topicContract, e.Path)
				}
			} else {
				byTopic[key] = Topic{TopicKey: key, Contract: c.topicContract}
				firstDir[key] = e.Path
			}
		}

		components = append(components, c)
	}

	if len(components) == 0 {
		return nil, fmt.Errorf("%w in this directory\nScaffold integrations first ('intropy int create <kind> -n <Name> ...'), then run 'intropy sys create' from the workspace root.", ErrNoComponents)
	}
	// Zero shared libraries is a valid workspace: a topic-free system never
	// references contracts, and a topic-bearing one gets them from the host
	// template's dependency. More than one is ambiguity the template cannot
	// resolve, so it stays an error regardless of the system's shape.
	if len(shared) > 1 {
		dirs := make([]string, len(shared))
		for i, s := range shared {
			dirs[i] = s.Path
		}
		return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
	}

	topics := make([]Topic, 0, len(byTopic))
	for _, t := range byTopic {
		topics = append(topics, t)
	}
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].Pubsub != topics[j].Pubsub {
			return topics[i].Pubsub < topics[j].Pubsub
		}
		return topics[i].Name < topics[j].Name
	})

	ports := make([]Port, 0, len(byPort))
	for name := range byPort {
		ports = append(ports, Port{Name: name})
	}
	sort.Slice(ports, func(i, j int) bool { return ports[i].Name < ports[j].Name })

	model := &Model{Components: components, Topics: topics, Ports: ports}
	if len(shared) == 1 {
		model.Shared = &shared[0]
	}
	return model, nil
}

// stringValue returns values[key] as a non-empty string, with errors that
// name the record so the user knows which project to fix.
func stringValue(e template.ScaffoldEntry, key string) (string, error) {
	return template.StringValue(e.Values, template.RecordPath(e.Path), key)
}

package template

import (
	"fmt"
	"path/filepath"
	"sort"
)

// BlockWiring is the wiring one scaffold record declares for its block:
// an optional topic and the named ports in the block kind's order (From
// before To for transactional blocks). The cross-component checks —
// duplicate ports, conflicting topic contracts — belong to system
// assembly; this is one record's view.
type BlockWiring struct {
	// Topic is nil for kinds without one.
	Topic *TopicKey
	// Contract is the C# contract type Topic's messages carry, valid only
	// when Topic is non-nil.
	Contract string
	// Ports carries the named ports in the kind's order. A topic block
	// with no port in its record (MissingPort) has none.
	Ports []string
	// MissingPort marks a topic-block record without a port value, so the
	// caller can warn without failing the record.
	MissingPort bool
}

// TopicKey identifies a topic within a system: the pub/sub component it
// lives on plus the topic name. Two records naming the same key declare
// the two halves of one contract.
type TopicKey struct {
	Pubsub string
	Name   string
}

// BlockParser reads one scaffold record's values into its block wiring.
// The parser owns per-record validation only; cross-component checks stay
// with the caller.
type BlockParser func(values map[string]any, recordPath string) (BlockWiring, error)

// BlockParsers is the set of block kinds system assembly accepts — the
// same registry `int adopt` validates new records against, so a record
// either passes everywhere or nowhere. Adding a kind is a constant, a
// parser, and an entry here.
var BlockParsers = map[string]BlockParser{
	BlockKindExtractor:     ParseTopicBlock,
	BlockKindLoader:        ParseTopicBlock,
	BlockKindTransactional: ParseTransactionalBlock,
}

// SupportedBlockKinds lists the registry keys sorted, for error messages.
func SupportedBlockKinds() []string {
	kinds := make([]string, 0, len(BlockParsers))
	for k := range BlockParsers {
		kinds = append(kinds, k)
	}
	sort.Strings(kinds)
	return kinds
}

// ValidateBlockRecord runs the parser registry entry for kind against
// values, exactly as system assembly will when it later reads the record.
// It returns an error for a kind absent from the registry or for any
// missing or malformed required value; recordPath names the record in
// those errors (a synthetic path like ".intropy/scaffold.json" is fine
// for a record not yet written).
func ValidateBlockRecord(kind string, values map[string]any, recordPath string) error {
	parse, ok := BlockParsers[kind]
	if !ok {
		return fmt.Errorf("unsupported block kind %q (sys create assembles %s)", kind, joinKinds())
	}
	_, err := parse(values, recordPath)
	return err
}

func joinKinds() string {
	kinds := SupportedBlockKinds()
	out := ""
	for i, k := range kinds {
		if i > 0 {
			out += ", "
		}
		out += k
	}
	return out
}

// ParseTopicBlock parses the wiring of a topic block (extractor, loader):
// a required topic and contract, and one optional port. A record without a
// port stays a valid component — it just gets no From/To in the generated
// wiring.
func ParseTopicBlock(values map[string]any, recordPath string) (BlockWiring, error) {
	var w BlockWiring
	topic, err := StringValue(values, recordPath, "topic")
	if err != nil {
		return w, err
	}
	contract, err := StringValue(values, recordPath, "contract")
	if err != nil {
		return w, fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values.", err)
	}
	pubsub, err := StringValueDefault(values, recordPath, "pubsub", "pubsub")
	if err != nil {
		return w, err
	}
	w.Topic = &TopicKey{Pubsub: pubsub, Name: topic}
	w.Contract = contract

	// No fallback for the port: a default would describe a binding the
	// rendered code doesn't use. A missing key is reported by the caller as
	// a warning; a present one must be a non-empty string.
	if _, ok := values["port"]; ok {
		port, err := StringValue(values, recordPath, "port")
		if err != nil {
			return w, err
		}
		w.Ports = []string{port}
	} else {
		w.MissingPort = true
	}
	return w, nil
}

// ParseTransactionalBlock parses the wiring of a transactional block:
// exactly two ports, From before To, and no topic. Both ports are required
// — a half-wired transactional block would render broken code.
func ParseTransactionalBlock(values map[string]any, recordPath string) (BlockWiring, error) {
	var w BlockWiring
	from, err := StringValue(values, recordPath, "fromPort")
	if err != nil {
		return w, err
	}
	to, err := StringValue(values, recordPath, "toPort")
	if err != nil {
		return w, err
	}
	w.Ports = []string{from, to}
	return w, nil
}

// StringValue returns values[key] as a non-empty string, with errors that
// name the record so the user knows which project to fix.
func StringValue(values map[string]any, recordPath, key string) (string, error) {
	v, ok := values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", recordPath, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", recordPath, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", recordPath, key)
	}
	return s, nil
}

// StringValueDefault is StringValue with a fallback for records that
// predate the value being recorded.
func StringValueDefault(values map[string]any, recordPath, key, fallback string) (string, error) {
	if _, ok := values[key]; !ok {
		return fallback, nil
	}
	return StringValue(values, recordPath, key)
}

// RecordPath renders the conventional <dir>/.intropy/scaffold.json path
// for a scaffold directory, for error messages.
func RecordPath(dir string) string {
	return filepath.Join(dir, filepath.FromSlash(ScaffoldRelPath))
}

// Package system assembles scaffolded integrations into a system host. It
// scans the workspace for the .intropy/scaffold.json records `int create`
// left behind, validates them into a system model, and builds the value
// payload the system-host template renders every declaration file from —
// Topics.cs, Ports.cs, the development and system definitions, and
// the csproj. The template library owns all generated content; this
// package owns workspace knowledge only.
package system

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// hostTemplate is the directory in the templates repo holding the system
// host: the shell plus every declaration file, rendered from the payload.
const hostTemplate = "system-host"

type CreateOptions struct {
	Name       string // system name as typed; PascalCase or kebab-case
	StartDir   string // workspace scan root; default "."
	OutputDir  string // default: the kebab-cased name
	Version    string // template release tag; default: latest
	Force      bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library; zero values target the
	// official library. GitHubBaseURL is a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// minFactsPayloadVersion is the lowest template-library release whose
// system-host consumes the facts-only payload. Named in the version gate's
// error so a user on an older release knows the floor.
const minFactsPayloadVersion = "v0.4.0"

// CreateResult is the machine-readable summary written when --output-json
// is set. Field names are stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`
	System    Summary        `json:"system"`
}

// Summary describes the assembled system; it loosely mirrors the model the
// host's `graph` verb prints.
type Summary struct {
	Name          string      `json:"name"`
	Components    []Component `json:"components"`
	Topics        []Topic     `json:"topics"`
	Ports         []Port      `json:"ports,omitempty"`
	SharedLibrary string      `json:"sharedLibrary"` // scaffold directory
}

func (o *CreateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full assembly: scan the workspace for scaffold records,
// validate them into a system model, build the value payload, and render
// the system-host template with it. All local validation happens before
// any network I/O.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if opts.Name == "" {
		return fmt.Errorf("a system name is required")
	}

	// Exact parity with the templates' `{{ .name | kebabcase }}`: sprig
	// delegates to xstrings, so OrderFlow and order-flow are equivalent.
	kebab := xstrings.ToKebabCase(opts.Name)
	if opts.OutputDir == "" {
		opts.OutputDir = kebab
	}

	entries, warnings := template.ListScaffolds(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := Assemble(entries, warnf)
	if err != nil {
		return err
	}
	model.Name = kebab

	payload, err := buildPayload(model, opts.OutputDir, kebab)
	if err != nil {
		return err
	}

	if err := template.Create(ctx, template.CreateOptions{
		Template:      hostTemplate,
		OutputDir:     opts.OutputDir,
		Version:       opts.Version,
		SetValues:     payload,
		Force:         opts.Force,
		NoInput:       true, // the template's values come from the payload, never prompts
		OnManifest:    requireFactsPayload,
		Stdin:         strings.NewReader(""),
		Stdout:        opts.Stdout,
		Stderr:        opts.Stderr,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
	}); err != nil {
		return err
	}

	// The template derives projectName/systemClass from the name; reading
	// them back from the record it just wrote keeps the result summary
	// honest about what was rendered.
	record, err := template.LoadScaffold(filepath.Join(opts.OutputDir, filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		return err
	}
	hostEntry := template.ScaffoldEntry{Path: opts.OutputDir, Scaffold: *record}
	if model.ProjectName, err = stringValue(hostEntry, "projectName"); err != nil {
		return fmt.Errorf("template %s did not derive the host project name: %w", hostTemplate, err)
	}
	if model.SystemClass, err = stringValue(hostEntry, "systemClass"); err != nil {
		return fmt.Errorf("template %s did not derive the system class name: %w", hostTemplate, err)
	}

	contracts := "no contracts project"
	if model.Shared != nil {
		contracts = "contracts from " + model.Shared.Path
	}
	fmt.Fprintf(opts.Stderr, "assembled system %q: %d component(s), %d topic(s), %d port(s), %s\n",
		model.Name, len(model.Components), len(model.Topics), len(model.Ports), contracts)

	return maybeWriteCreateResult(opts, record, model)
}

// requireFactsPayload rejects a system-host template release that predates
// the facts-only payload: one that still requires sharedContracts consumes
// the pre-join payload shape (CLI-derived field identifiers and a csproj
// include path), which this CLI no longer produces. The gate runs before any
// output is written so an old release fails loudly instead of rendering a
// host that cannot compile.
func requireFactsPayload(t *template.Template) error {
	required, _ := t.Spec.Parameters["required"].([]any)
	for _, r := range required {
		if name, _ := r.(string); name == "sharedContracts" {
			return fmt.Errorf("system-host template %s requires the sharedContracts payload: it predates facts-only payloads (field identifiers and the csproj reference moved into the template) — use template release %s or newer", t.Metadata.Name, minFactsPayloadVersion)
		}
	}
	return nil
}

// sharedPath reports the detected contracts sibling for the JSON summary;
// empty when the workspace has none.
func sharedPath(m *Model) string {
	if m.Shared == nil {
		return ""
	}
	return m.Shared.Path
}

func maybeWriteCreateResult(opts CreateOptions, record *template.Scaffold, model *Model) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:  hostTemplate,
		Owner:     record.Owner,
		Repo:      record.Repo,
		Version:   record.Version,
		OutputDir: absOut,
		Values:    record.Values,
		System: Summary{
			Name:          model.Name,
			Components:    model.Components,
			Topics:        model.Topics,
			Ports:         model.Ports,
			SharedLibrary: sharedPath(model),
		},
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output-json: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

package system

import (
	"fmt"
	"path/filepath"
)

// buildPayload assembles the value map passed as SetValues to the
// system-host template. The payload carries workspace facts only — topic and
// port names, component wiring, the detected contracts sibling — and the
// template derives everything that exists only inside the generated
// files: the Topics/Ports field identifiers, the joins between
// components and those fields, and the csproj ProjectReference path.
//
// The contracts sibling travels as a relative include: the template renders
// it verbatim into the host csproj's ProjectReference, and the host is
// always created as a sibling of the contracts project, so the CLI's
// workspace-relative path and the include differ only by the leading "../".
// Computing the include here keeps the templates (and the test fixtures that
// mirror them) free of host-side path arithmetic.
func buildPayload(m *Model, outputDir, kebab string) (map[string]any, error) {
	topics := make([]any, len(m.Topics))
	for i, t := range m.Topics {
		topics[i] = map[string]any{
			"pubsub":   t.Pubsub,
			"name":     t.Name,
			"contract": t.Contract,
		}
	}

	ports := make([]any, len(m.Ports))
	for i, c := range m.Ports {
		ports[i] = map[string]any{
			"name": c.Name,
		}
	}

	components := make([]any, len(m.Components))
	for i, c := range m.Components {
		// Kind is verbatim: Assemble already validated it against the
		// parse registry. The wiring fields follow the component's shape,
		// not its kind — a topic carries topic, one port port, two ports
		// fromPort/toPort — and the template resolves each name to the
		// field identifier it derived for the topic or port. The keys match
		// the transactional scaffold record's: the template library's
		// system-host reads fromPort/toPort (template release v0.4.0+).
		entry := map[string]any{
			"appId": c.AppID,
			"kind":  c.Kind,
		}
		if c.Topic != nil {
			entry["topic"] = map[string]any{
				"pubsub": c.Topic.Pubsub,
				"name":   c.Topic.Name,
			}
		}
		switch len(c.Ports) {
		case 0:
		case 1:
			entry["port"] = c.Ports[0]
		default:
			entry["fromPort"] = c.Ports[0]
			entry["toPort"] = c.Ports[1]
		}
		components[i] = entry
	}

	payload := map[string]any{
		"name":       kebab,
		"topics":     topics,
		"ports":      ports,
		"components": components,
	}
	if m.Shared != nil {
		include, err := contractsInclude(outputDir, *m.Shared)
		if err != nil {
			return nil, err
		}
		payload["sharedContracts"] = map[string]any{
			"name":    m.Shared.Name,
			"include": include,
		}
	}
	return payload, nil
}

// contractsInclude computes the ProjectReference Include path from the
// host's output directory to the shared library's csproj, slash-separated.
func contractsInclude(outputDir string, shared SharedLibrary) (string, error) {
	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		return "", err
	}
	absShared, err := filepath.Abs(shared.Path)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absOut, absShared)
	if err != nil {
		return "", fmt.Errorf("compute path from %s to shared contracts project %s: %w", outputDir, shared.Path, err)
	}
	return filepath.ToSlash(filepath.Join(rel, shared.Name+".csproj")), nil
}

