using System.Text.Json;
using System.Text.Json.Serialization;
using Dapr.Client;
using Dapr.Messaging.PublishSubscribe.Extensions;
using Intropy.BusinessIncidentService.Client;
using Intropy.Contracts.BusinessIncidentService;
using Intropy.Framework.Blocks.Extractor.Steps;
using Intropy.Framework.Core.Configuration;
using Intropy.IdempotencyService.Client;
using Extractor.Perfion.Helpers;
using Microsoft.Extensions.DependencyInjection;
using Intropy.Telemetry.ConsoleApp;
using Extractor.Perfion.Adapters;
using Extractor.Perfion.Batch;
using Extractor.Perfion.Batch.Steps;
using Extractor.Perfion.Configuration;
using Extractor.Perfion.Pipelines;
using Extractor.Perfion.Pipelines.Streamed;
using Extractor.Perfion.Process;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

var configuration = ConfigurationHelper.BuildConfiguration();
var services = new ServiceCollection();
var environment = Environment.GetEnvironmentVariable("DOTNET_ENVIRONMENT") ?? "Production";
var daprPort = Environment.GetEnvironmentVariable("DAPR_HTTP_PORT") ?? "3500";

services.AddSingleton(configuration);

// Observability
services.AddLogging(b =>
{
    b.AddConfiguration(configuration.GetSection("Logging"));
    b.AddSimpleConsole(o =>
    {
        o.SingleLine = true;
        o.TimestampFormat = "HH:mm:ss ";
    });
});
services.AddOpenTelemetry(conf =>
{
    conf.ServiceNamespace = Constants.CustomerName;
    conf.ServiceName = Constants.ComponentName;
    conf.Environment = environment;
});

// Infrastructure clients
services.AddIdempotencyServiceClient(c =>
{
    c.AppId = configuration.GetValue<string>("PlatformServices:IdempotencyServiceAppId") ??
              "iss-idempotency-service.services";
    c.DaprHttpEndpoint = $"http://127.0.0.1:{daprPort}";
});

services.AddBusinessIncidentServiceClient(c =>
{
    c.AppId = configuration.GetValue<string>("PlatformServices:BusinessIncidentServiceAppId")
              ?? "bis-business-incident-service.services";
});

services.AddDaprPubSubClient();

// Configure framework
services.AddIntropyFramework(x =>
{
    x.ComponentName = Constants.ComponentName;
    x.ServiceNamespace = Constants.CustomerName;
});

services.AddAzureBlobStorageAdapter(configuration.GetSection("AzureBlobStorage").Get<AzureBlobStorageOptions>()!);

// JSON serialization — source records are read via attribute-based converters that ignore
// these options; the options govern the JSONL output written for each entity and the export
// event published by the Dapr client below. Web defaults (camelCase, case-insensitive) with
// nulls omitted keep the output compact. No downstream consumer contract exists yet.
var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web)
{
    DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
};
services.AddSingleton(jsonOptions);

// Dapr client used by the export publisher; shares the JSON options so the published
// CloudEvent data matches the JSONL casing. Built directly (the AddDaprClient DI helper
// lives in Dapr.AspNetCore, which this console job does not reference).
services.AddSingleton(new DaprClientBuilder()
    .UseJsonSerializationOptions(jsonOptions)
    .Build());

// Ingest options (container + blob prefixes) bound from configuration.
services.AddSingleton(configuration.GetSection("Ingest").Get<IngestOptions>()!);

// PubSub options
services.AddSingleton(configuration.GetSection(PubSubOptions.SectionName).Get<PubSubOptions>()!);

// Batch detection + streamed sub-pipelines (one IStreamedPipeline per Perfion entity type).
services.AddSingleton<BatchReceiver>();
services.AddPerfionStreamedPipelines();

// The outer batch pipeline: detect → run each streamed sub-pipeline → serialize the export
// event → publish it to the Dapr topic → archive the consumed inputs. Steps are constructed
// directly in the lambda (mirroring the streamed-pipeline registration), pulling their
// dependencies from the provider.
services.AddBatchPipeline<BatchReceiver.ReceivedBatch, PerfionBatchContext>(Constants.ComponentName,
    (pb, sp) => pb
        .WithReceiver(new PerfionBatchReceiveStep(
            sp.GetRequiredService<BatchReceiver>(),
            sp.GetRequiredService<ILogger<PerfionBatchReceiveStep>>()))
        .WithStreamedPipelines(sp, sp.GetServices<IStreamedPipeline>())
        .WithSerializer(new PerfionExportEventSerializeStep(
            sp.GetRequiredService<IngestOptions>(),
            sp.GetRequiredService<ILogger<PerfionExportEventSerializeStep>>()))
        .WithSender(new DaprTopicPublisher<PerfionBatchContext>(
            sp.GetRequiredService<DaprClient>(),
            sp.GetRequiredService<PubSubOptions>().PubSubName,
            sp.GetRequiredService<PubSubOptions>().TopicName,
            Constants.ExportEventSource,
            Constants.ExportEventType))
        .WithArchiver(new PerfionBatchCompleteStep(
            sp.GetRequiredService<IAzureBlobStorageAdapter>(),
            sp.GetRequiredService<IngestOptions>(),
            sp.GetRequiredService<ILogger<PerfionBatchCompleteStep>>()))
        // Trigger a business incident when the run fails and resolve it when it succeeds.
        // Keyed on the export id (the timestamp batch folder) so routing is stable across
        // CronJob retries.
        .WithBusinessIncidents(
            sp.GetRequiredService<IBusinessIncidentServiceClient>(),
            messageIdExtractor: ctx => ctx.Batch?.ExportId ?? "unknown",
            subjectExtractor: ctx => ctx.Batch?.ExportId ?? "unknown"));

services.AddSingleton<BatchRunner>();

// Run the batch once and exit with its status code.
var provider = services.BuildServiceProvider();

// Flush OTLP telemetry before this short-lived console app exits; without it the batch
// exporter's spans/metrics/logs are dropped on process exit.
using var telemetry = new OpenTelemetryScope(provider);

using var cts = new CancellationTokenSource();
Console.CancelKeyPress += (_, e) =>
{
    e.Cancel = true;
    cts.Cancel();
};

// Dapr sidecar lifecycle (this runs as a Kubernetes CronJob). The batch publishes the export
// event and calls the idempotency service over Dapr, so the sidecar must be up before we run —
// and it must be told to shut down afterwards, otherwise the sidecar keeps running and the Job
// pod never completes. Pattern lifted from Intropy.Framework.Hosting's TransactionalIntegrationRunner.
var dapr = provider.GetRequiredService<DaprClient>();
var logger = provider.GetRequiredService<ILoggerFactory>().CreateLogger("Program");

try
{
    using var sidecarCts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
    await dapr.WaitForSidecarAsync(sidecarCts.Token);
}
catch (Exception e)
{
    logger.LogError(e, "Dapr sidecar did not become available");
    return 1;
}

try
{
    var runner = provider.GetRequiredService<BatchRunner>();
    return await runner.RunAsync(cts.Token);
}
finally
{
    try
    {
        await dapr.ShutdownSidecarAsync();
    }
    catch (Exception e)
    {
        logger.LogWarning(e, "Failed to shut down Dapr sidecar");
    }
}

