func TestResolveSetPinsDerivedValue(t *testing.T) {
	// The adoption case: the template derives appId from the name, but an
	// adopted component already has a real app-id. --set must win.
	tmpl := buildTemplate(map[string]any{
		"type":     "object",
		"required": []any{"name"},
		"properties": map[string]any{
			"name": map[string]any{"type": "string"},
		},
	}, []string{"name"}, map[string]string{
		"appId": "{{ .name | kebabcase }}",
		"port":  "{{ .name | kebabcase }}-source",
	})

	out, err := Resolve(tmpl, nil, nil, map[string]any{
		"name":  "Extractor.Perfion",
		"appId": "product-distribution-extractor-perfion",
	}, nil)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if out["appId"] != "product-distribution-extractor-perfion" {
		t.Errorf("appId = %v, want the pinned --set value", out["appId"])
	}
	// An unpinned derived key still derives from the (pinned) inputs.
	if out["port"] != "extractor-perfion-source" {
		t.Errorf("port = %v, want derived extractor-perfion-source", out["port"])
	}
}

