func TestRenderCustomerHost(t *testing.T) {
	out := os.Getenv("CUSTOMER_HOST_OUT")
	if out == "" {
		t.Skip("CUSTOMER_HOST_OUT not set")
	}
	lib := templatesDir(t)
	tmpl, err := template.LoadTemplate(filepath.Join(lib, "system-host", "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	payload := map[string]any{
		"name": "product-distribution",
		"topics": []any{
			map[string]any{"pubsub": "product-distribution-pubsub", "name": "sbt-test-product-extractor-001", "contract": "ExportEvent", "contractNamespace": "Shared.Extractor"},
		},
		"ports": []any{map[string]any{"name": "perfion-extractor-source"}},
		"components": []any{
			map[string]any{"appId": "product-distribution-extractor-perfion", "kind": "extractor", "topic": map[string]any{"pubsub": "product-distribution-pubsub", "name": "sbt-test-product-extractor-001"}, "port": "perfion-extractor-source"},
		},
		"sharedContracts": map[string]any{"name": "Shared", "include": "../shared/src/Shared.csproj"},
	}
	values, err := template.Resolve(tmpl, nil, nil, payload, nil)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(out, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := template.RenderFiltered(filepath.Join(lib, "system-host", "skeleton"), out, values, tmpl.Spec.Files); err != nil {
		t.Fatalf("render: %v", err)
	}
	data, _ := os.ReadFile(filepath.Join(out, "Topics.cs"))
	t.Logf("Topics.cs:\n%s", data)
}
